#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import zlib from 'zlib';

const target=process.cwd();
const payload={"package.json":"","README.md":"","README_NASADENIE_0.22.txt":"","RELEASE_NOTES.md":"","RELEASE_NOTES_0.22.md":"","src/data/contractTasks.json":"","src/data/seed.json":"","src/lib/storage.ts":"","src/views/ContractSpending.css":"","src/views/ContractSpending.tsx":"","src/views/ItCosts.css":"","src/views/ItCosts.tsx":"","src/views/TechnologyCatalog.css":"","src/views/TechnologyCatalog.tsx":""};
const stamp=new Date().toISOString().replace(/[:.]/g,'-');
const backup=path.join(target,`backup-before-v0220-${stamp}`);

function fail(message){console.error('ERROR:',message);process.exit(1)}
if(!fs.existsSync(path.join(target,'package.json'))) fail('Spusti installer v koreni projektu IS Riadenie odboru.');
let pkg={};try{pkg=JSON.parse(fs.readFileSync(path.join(target,'package.json'),'utf8'))}catch{fail('package.json sa nepodarilo nacitat.');}
if(pkg.name!=='is-riadenie-odboru') fail('Tento priecinok nevyzera ako projekt is-riadenie-odboru.');
console.log('IS Riadenie odboru - upgrade na v0.22.0');
console.log('Aktualna verzia:',pkg.version||'nezistena');
fs.mkdirSync(backup,{recursive:true});
let written=0,backed=0;
for(const [rel,encoded] of Object.entries(payload)){
  const destination=path.join(target,rel);
  if(fs.existsSync(destination)){
    const backupPath=path.join(backup,rel);fs.mkdirSync(path.dirname(backupPath),{recursive:true});fs.copyFileSync(destination,backupPath);backed++;
  }
  fs.mkdirSync(path.dirname(destination),{recursive:true});
  fs.writeFileSync(destination,zlib.gunzipSync(Buffer.from(encoded,'base64')));written++;
  console.log('WRITE',rel);
}
for(const cache of ['dist','.vite',path.join('node_modules','.vite')]){const full=path.join(target,cache);if(fs.existsSync(full)){fs.rmSync(full,{recursive:true,force:true});console.log('CLEAR',cache)}}
const installed=JSON.parse(fs.readFileSync(path.join(target,'package.json'),'utf8'));
if(installed.version!=='0.22.0') fail('Kontrola verzie zlyhala.');
const tech=fs.readFileSync(path.join(target,'src/views/TechnologyCatalog.tsx'),'utf8');
const costs=fs.readFileSync(path.join(target,'src/views/ItCosts.tsx'),'utf8');
const contracts=fs.readFileSync(path.join(target,'src/views/ContractSpending.tsx'),'utf8');
if(!tech.includes('Technológie · služby · náklady · riziko')) fail('Technology Intelligence sa nepodarilo overit.');
if(!costs.includes('Úlohy 10 / 22 / 25')) fail('Prepínac financneho modulu sa nepodarilo overit.');
if(!contracts.includes('KONTRAKTOVÉ ČERPANIE')) fail('Kontraktove cerpanie sa nepodarilo overit.');
console.log('');
console.log(`VERIFIED: v0.22.0 nainstalovana. Suborov zapisanych: ${written}, zalohovanych: ${backed}.`);
console.log('Zaloha:',backup);
console.log('Nasledne spusti npm run build alebo bezny Vercel deployment.');
